import{_ as l,o as i,c as b,a3 as p}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"ai摘录_网站内容收集","description":"","frontmatter":{"translationSource":{"title":"ai摘录_网站内容收集","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JiJOcVVrOL60gHxdI4OBje","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/ai-excerpts-website-content-collection"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/ai-excerpts-website-content-collection"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/ai-excerpts-website-content-collection"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/ai-excerpts-website-content-collection"}]]},"headers":[],"relativePath":"zh/ai-excerpts-website-content-collection.md","filePath":"zh/page-JiJOcVVrOL60gHxdI4OBje.md"}'),a={name:"zh/ai-excerpts-website-content-collection.md"};function e(o,r,t,n,c,s){return i(),b("div",null,[...r[0]||(r[0]=[p('<div class="logistics-content"><span class="logistics-source-anchor" id="ai摘录-网站内容收集" aria-hidden="true"></span><h1 id="ai摘录-网站内容收集" tabindex="-1">ai摘录_网站内容收集 <a class="header-anchor" href="#ai摘录-网站内容收集" aria-label="Permalink to &quot;ai摘录\\_网站内容收集&quot;">​</a></h1><blockquote><p>源页面 ID：<code>JiJOcVVrOL60gHxdI4OBje</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JiJOcVVrOL60gHxdI4OBje" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>JMY 的网站建设 —— 群聊记录收集稿<br> 来源：局_合并.txt（99578 条，2026-09-07 11:46 至 2026-10-23 00:22）<br> 整理范围：2026-10-08 至 2026-10-22（10-11 之后最密集）<br> 说明：只摘录原文，未做推测；数字与原文一致。每条给出「讨论内容 / 提出者与时间 / 结论 / 原文」。<br> 已有页面写过的内容（网站名称讨论本身、盒え猫明暗配色与鸿蒙字体、S 建议不用正黑正白、禁右键防源码）此处不重复，仅在与新结论直接相关时引用一句。</p><p><span id="source-block-4hukmCUg3diq9h42bvLIub"></span></p><h2 id="" tabindex="-1">================================================================ <a class="header-anchor" href="#" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【一】缘起与定位</p><ol><li><p>起点：把任务板（腾讯文档）做成网站<br> 谁提的：c（10-08 21:42），K 回应；JMY 当晚开工<br> 结论：已定（方向确定并已实施）<br> 原文：c「把你的任务版做成网站（」；K「那是个很艰巨的任务了，先写到任务板上吧（）」；<br> JMY（10-08 21:46）「OK基础代码写完了」「把我之前做的网站的代码套点」</p></li><li><p>网站要取代文档，成为对外发布端<br> 谁提的：凯（10-18 15:48、10-20 00:53）、沃（10-20 00:52）<br> 结论：已定（群内倾向明确）<br> 原文：凯「要不然以后蓝图就弃用文档改用网站吧」「我说实话这网站明显比文档好用」<br> 「任务版留给群友」「网站留给抄蓝图的」「把人引流到网站而不是文档」<br> 言「那之后就这个作为发布端吗」→ 凯「我看行」；沃「我感觉还是网站更好一些」</p></li><li><p>前端到底放什么内容 —— 提过一次，没有结论<br> 谁提的：-（10-11 22:04）<br> 结论：未定<br> 原文：「@JMY 你的前端暂时打算放哪些内容？感觉只有指路版上的基建内容值得放。其实维护的不是文档而是知识库了（当然不知道为什么感觉任务版公约一直是废纸）。」<br> 随后 K 只回了「因为任务简报都是废纸（」，内容范围没有继续讨论。</p></li><li><p>内容不宜过杂的提醒<br> 谁提的：盒え猫（10-20 23:40），K 补充（10-20 23:41）<br> 结论：未定（只是提醒）<br> 原文：盒え猫「几乎无用且杂乱的功能的话」「会使得你这个网页比较臃肿」；<br> K「还好，收纳在一起不要盖过主要功能就行」</p></li></ol><p><span id="source-block-ayYvEFuBZ0jMuXBGo3eGpb"></span></p><h2 id="-1" tabindex="-1">================================================================ <a class="header-anchor" href="#-1" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【二】网站名字（候选一堆，至今未定）</p><ol><li><p>中文名候选「宏科院智网」<br> 谁提的：JMY（10-19 19:27），来源是直播间问老大<br> 结论：未定（提出后无人正式拍板，后续还被记错成「知网」）<br> 原文：「刚刚在直播间问老大了叫宏科院智网」</p></li><li><p>中文名候选「宏科院知网」<br> 谁提的：君（10-19 19:22）；盒え猫 10-20 00:57 复述<br> 结论：未定（被当成误记）<br> 原文：君「宏科院知网」；盒え猫「我寻思好像是叫宏科院知网」</p></li><li><p>中文名候选「塔卫二基建终端」/「终末地基建终端」/「基站」<br> 谁提的：盒え猫（10-19 19:23）、区（10-19 19:21）、沃（10-20 01:00）<br> 结论：未定<br> 原文：盒え猫「塔卫二基建终端？」；区「基建网站，叫基站吧」；<br> 沃「全称叫终末地基建终端」；沃（10-20 01:14）「明日方舟：终末地基建终端」</p></li><li><p>玩笑向候选（言主张接地气）<br> 谁提的：言（10-20 00:58、01:12）、華（10-20 01:03）<br> 结论：未定（当玩笑处理）<br> 原文：言「我想叫 宏科院赤石网」「宏科院赤石中心🤓」「宏科院司石台🤓」；華「宏科院赤石科学终端」</p></li><li><p>英文名候选与争议<br> 谁提的：沃（10-20 01:12、01:14）、曜（10-20 01:13-01:15）、盒え猫（10-19 19:24）<br> 结论：未定，且 infrastructure 被指用词不对<br> 原文：沃「Arknights: Endfield Infrastructure Terminal」「AEIT」；<br> 曜「terminal 作为查询终端还挺对的」「infrastructure 这里感觉不对」「因为此基建非彼基建」；<br> 曜「terminal.endfield-industry.com」；盒え猫「Talos-II Industry Terminal」</p></li><li><p>组名式候选（讨论跑偏到组名）<br> 谁提的：鸟（10-20 01:28）、華（10-20 01:28）、盒え猫（10-20 01:28-01:29）<br> 结论：未定（被指出「网站名变成组名了」）<br> 原文：鸟「aic-rookie research club」；華「Green Handymanufacture Research Club」「green hand - 小杯」；<br> 盒え猫「所以我们怎么从」「网站名」「变成组名了」</p></li><li><p>搞笑彩蛋设想<br> 谁提的：盒え猫（10-20 01:32-01:33）<br> 结论：未定（仅设想）<br> 原文：「搞笑一点的做个彩蛋」「触发神秘小巧思后」「整个界面变成手绘涂鸦风格」「所有英文字体变成papyrus」「名字变成kuangkuangkuang」</p></li><li><p>截至 10-22 仍未定<br> 谁提的：JMY（10-20 22:55、10-22 18:44）<br> 结论：未定<br> 原文：JMY「所以网站对外宣传的中文名和英文名到底叫啥啊」；<br> JMY「所以新域名到底叫啥」「我还是没想好」；四卡一「别光问我（」</p></li><li><p>一个客观事实：页面标题里写的是「ENDFIELD 1.5 GUIDE」<br> 谁提的：JMY 贴出的 HTML（10-18 15:43）<br> 结论：已存在（是否为正式名未讨论过）<br> 原文：&lt;title&gt;绑定游戏账号 - ENDFIELD 1.5 GUIDE&lt;/title&gt;</p></li></ol><p><span id="source-block-RpGmt6Ntkd3hdOUBR2zhGP"></span></p><h2 id="-2" tabindex="-1">================================================================ <a class="header-anchor" href="#-2" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【三】域名</p><ol><li><p>现在用的是 pythonanywhere 免费子域<br> 谁提的：JMY（10-08 21:50 起，反复发链接）<br> 结论：已定（临时）<br> 原文：JMY「这是我申请的免费域名」；链接一律为 <a href="https://zmdjj.pythonanywhere.com/" target="_blank" rel="noreferrer">https://zmdjj.pythonanywhere.com/</a></p></li><li><p>候选域名 endfieldindustry4ka1.cc<br> 谁提的：JMY（10-11 22:58、10-15 00:22）<br> 结论：未定（被嫌长）<br> 原文：JMY「新域名就叫endfieldindustry4ka1.cc吧」「.cc便宜」；<br> JMY「endfieldindustry4ka1.cc这个域名咋样」；鸟「好长啊（」；区「我勒个四卡一」</p></li><li><p>缩短提案<br> 谁提的：鸟（10-15 00:25）<br> 结论：未定<br> 原文：「endfield4ka1.cc」</p></li><li><p>10-22 决定先不买<br> 谁提的：JMY（10-22 23:26、23:28）<br> 结论：已定（暂缓）<br> 原文：JMY「先不买域名了」「服务器还没搞定」；<br> 笑对人生「这不用cloudflare挂或者用免费域名么」</p></li></ol><p><span id="source-block-2CN9sCoMWEu2P5whSL2gwK"></span></p><h2 id="-3" tabindex="-1">================================================================ <a class="header-anchor" href="#-3" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【四】网站放什么内容</p><ol><li><p>1.5 版本基建指南（应龙关/武陵/景玉谷/首墩 + 每章讲解视频 + 蓝图码一键复制）<br> 谁提的：JMY（10-14 23:40，自述功能清单第 1 条）<br> 结论：已实现<br> 原文：「整理了应龙关、武陵、景玉谷、首墩全地图的智能最大毛产出基建蓝图，每个章节都配了讲解视频；正文里的所有蓝图分享码自动带上一键复制按钮」</p></li><li><p>工业数据实时看板（绑森空岛账号，看发电量/电力盈余/产线产量）<br> 谁提的：JMY（10-14 23:40 第 2 条；10-13 19:44 开始测试）<br> 结论：已实现<br> 原文：「绑定自己的森空岛账号后，不用登游戏就能实时查看总发电量、电力盈余、每条产线的运行产量」<br> JMY（10-13 19:44）「（在网站内实时查看发电量与工业简报）」</p></li><li><p>物流技术手册<br> 谁提的：JMY（10-14 23:40 第 3 条）<br> 结论：已实现<br> 原文：「收录了社区完整的阻塞流理论、产线设计原理、优先级机制、各种游戏内 bug 的研究解析」</p></li><li><p>自助管理后台（上传 Word 自动解析、改 Markdown、绑 B 站视频、改密码、看访问量）<br> 谁提的：JMY（10-14 23:40 第 4 条；10-08 22:55 已提过）<br> 结论：已实现<br> 原文：「支持直接上传 Word 文档自动解析成网页，也可以手动编辑 Markdown 内容、给每个章节绑定 B 站讲解视频、修改管理员密码」「后台还能看网站累计访问量」</p></li><li><p>蓝图投稿（模块化蓝图合集 + 投稿审核）<br> 谁提的：BEAR（10-11 20:01），JMY 当天回应<br> 结论：已定（做了）<br> 原文：BEAR「我希望有一个界面，存模块化蓝图」「如果支持大家投稿给我们审核就更好了」；<br> JMY（10-11 20:04）「游客可以提交自己的蓝图投稿，管理员在后台审核通过之后自动显示在前台」；<br> BEAR「我觉得可以」，沃沃奶糖「我觉得行」</p></li><li><p>工具箱 / 友情链接 / 关于我们<br> 谁提的：JMY（10-14 23:57、10-18 13:30、10-21 21:04）<br> 结论：已实现<br> 原文：JMY「网站里的工具箱把任务版的一些链接搬过去了」「点名字就可以跳转了」；<br> K 提友情链接后 JMY「我加进网站了」；<br> JMY（10-21 21:04）「网站更新新功能（关于我们），里面有关于sky这个蓝图等东西的简介」</p></li><li><p>论坛（子网站）—— 提出来当天就砍了<br> 谁提的：JMY（10-18 13:43-14:04），K/凯 反对<br> 结论：被否决（JMY 自己删了文件）<br> 原文：JMY「论坛弄完后就搞成这个网站的子网站了」「OK论坛的基础代码改完了」「我要搞个论坛」；<br> 凯「真的有人看吗」→ JMY「貌似没人看」；<br> K「不备案的搞论坛这种安全性低的东西，容易出事吧（」；<br> JMY「要备案的」「实在不行我不做了」→「不做了」「删文件了」</p></li><li><p>视频要不要大量上站 —— 有顾虑<br> 谁提的：盒え猫（10-10 20:42），JMY 回应<br> 结论：未定（先压画质/后台添加）<br> 原文：盒え猫「不然往里塞视频又得费群u老大劲（」；JMY「我可以写一个在后台添加的代码，这样就不用一个一个写了」；<br> JMY（10-10 20:37）「就是怕存储空间不够」</p></li></ol><p><span id="source-block-eoWe5Ff9ZxNarF6hmjeMpe"></span></p><h2 id="-4" tabindex="-1">================================================================ <a class="header-anchor" href="#-4" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【五】技术方案与托管</p><ol><li><p>建站语言与平台：Python + pythonanywhere<br> 谁提的：盒え猫 问、JMY 答（10-08 21:40）<br> 结论：已定（现状）<br> 原文：盒え猫「以及python做网页吗（？」；JMY「是的」</p></li><li><p>静态还是动态 —— 群友判断不一致<br> 谁提的：K（10-21 00:52）、-（10-21 00:52）、JMY（10-21 00:50-00:51）<br> 结论：未定（实际是带后端交互的动态站）<br> 原文：K「现在不是静态吗（」；-「不知道怎么搞的，但不像」「加了在线客服一堆东西」；<br> JMY「主要买个服务器方便调用skd数据」</p></li><li><p>迁移方案：两条路<br> 谁提的：JMY（10-21 00:50）<br> 结论：未定<br> 原文：「现在就两种方法」「1」「买个服务器和一个域名把东西全搬上去」「2」「冲个pythonanywhere的会员70块钱一个月」</p></li><li><p>群友建议的替代托管<br> 谁提的：-（10-21 00:51-01:04）、笑对人生（10-22 23:35）、烫（10-18 13:37）<br> 结论：未采纳（JMY 仍倾向自购服务器）<br> 原文：-「我觉得不如github pages」「你用cloudflare不也能托管」「为什么不用图床」<br> 「建议早点抛弃pythonanywhere，你在这种平台上面测试都测不明白」；<br> 烫「图片你去搞个免费cdn就好了」；<br> JMY「不如直接买个服务器」「没那么多事」</p></li><li><p>服务器选型：甲骨文免费机<br> 谁提的：JMY（10-22 21:43、22:11）<br> 结论：未定（卡在要绑银行卡）<br> 原文：「找了个免费1核1g的服务器但要绑定银行卡」「账号你创吧」「我没卡」；<br> 「甲骨文服务器是免费的」；Disadvantages「这么便宜」</p></li><li><p>存储与容量<br> 谁提的：JMY（10-15 00:31、10-18 13:31、10-18 13:34）<br> 结论：已确认（是硬约束）<br> 原文：JMY「目前网站存储空间才512mb」；曜「话说这服务器能塞进多少东西」→ JMY「512mb」；<br> JMY「整个网站图片就10mb」；曜「那非常可惜我们的任务版里的图片大概放不进去了」「可能考虑弄个图片代理服务器」</p></li><li><p>服务器在境外（影响速度与备案）<br> 谁提的：凯（10-15 22:48）、JMY 确认<br> 结论：已确认<br> 原文：凯「网站的服务器不在中国对吧」→ JMY「是的」；凯「有点小卡」</p></li></ol><p><span id="source-block-CRJMx7U3Pg7Iejs8UaJG0A"></span></p><h2 id="-5" tabindex="-1">================================================================ <a class="header-anchor" href="#-5" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【六】花了多少钱（数字照抄）</p><ol><li><p>pythonanywhere 会员价<br> 谁提的：JMY（10-13 23:59、10-21 00:50）<br> 结论：已确认（嫌贵）<br> 原文：「一个月10刀还是太超标了」；「冲个pythonanywhere的会员70块钱一个月」；<br> （10-13 23:59）「我突然发现我的这个网站冲会员就可以直接自定义域名了后面不用加上pythonanywhere了」</p></li><li><p>服务器价<br> 谁提的：JMY（10-15 00:13、10-18 12:55）、断懒（10-15 00:21）<br> 结论：已确认（贵，未买）<br> 原文：JMY「主要服务器贵我之前看正常的好像一个月25」；<br> JMY「这服务器咋这么贵」「一季度5000多」「不买了」；<br> 断懒「第一次用这种服务器，说的是300一年」</p></li><li><p>域名价<br> 谁提的：JMY（10-15 00:13、00:19、10-22 22:10）、笑对人生（10-22 23:35）<br> 结论：已确认（便宜）<br> 原文：JMY「域名便宜买个.cc的一年就几十块钱」；<br> JMY「你看这个域名加上服务器一年大概七八十左右」；<br> JMY「算了一下服务器免费的，域名一年30左右」；<br> 笑对人生「我看人聊这个说xyz域名头年才几块钱」「续费400多」</p></li><li><p>自己垫钱与攒钱<br> 谁提的：JMY（10-15 00:13、10-18 13:37、10-18 13:46）<br> 结论：未定（靠零花钱）<br> 原文：「我自己垫点」；「明年暑假我估计能攒够服务器的钱了」；「谁能资助我个服务器」</p></li></ol><p><span id="source-block-USDXTHlUy55TZwKJvBNLyc"></span></p><h2 id="-6" tabindex="-1">================================================================ <a class="header-anchor" href="#-6" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【七】备案</p><ol><li><p>服务器在境外 → 不用备案<br> 谁提的：JMY（10-22 22:12）、浅仓透（10-14 21:54）、凯（10-14 21:42）<br> 结论：已定（按现状不备案）<br> 原文：JMY「而且服务器是国外的不用备案」；浅仓透「（这意思是不是服务器在境外就不用备案」→「对」；<br> 凯「但是总之是不需要备案也不需要域名的」</p></li><li><p>反方意见：严格来说仍需备案<br> 谁提的：K（10-14 21:40、21:57）<br> 结论：存疑（未形成统一意见）<br> 原文：「严格来说，是不是自己的服务器不影响需不需要备案，应该还是需要的，不过不备案问题也不大」<br> 「（其实提供服务的组织或个人在国内就要」；<br> 浅仓透「只能说有风险，没有强制要你备案(」；K「评价为没人会管的（」</p></li><li><p>备案分两种：域名备案 + 公安（网安）备案<br> 谁提的：浅仓透（10-14 21:43）、K（10-14 21:46）<br> 结论：已确认（常识性说明）<br> 原文：浅仓透「服务器在国内域名备案后还要公安备案」「我的域名做了双备案，虽然上面什么都没放(」；<br> K「类似这种，左边是域名备案，右边是网安(公安)备案」</p></li></ol><p><span id="source-block-p9YHPNN3ZgMlA88742hQkF"></span></p><h2 id="-7" tabindex="-1">================================================================ <a class="header-anchor" href="#-7" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【八】已实现的功能（按时间）</p><ol><li>功能上线时间线（全部为 JMY 自述，逐条可查）<br> 结论：已实现<br> 原文与时间： <ul><li><p>10-10 20:05 搜索已存在：君「搜索（）」→ JMY「有」</p></li><li><p>10-11 20:04 蓝图投稿 + 后台审核</p></li><li><p>10-13 10:37/11:20 网站图标更换（「网站图标就用这个吧」「网站图标已更改」）</p></li><li><p>10-13 11:15 图片重复 bug 修复（「图片重复bug已解决,现在网站不会出现重复的图片了」）</p></li><li><p>10-13 19:10 抽卡记录（「现在网站实装了看抽卡记录」）</p></li><li><p>10-14 00:55 静态网页并入（曜的 mdBook 页面）</p></li><li><p>10-14 20:01 一键复制蓝图码（「网站现在可以一键复制蓝图码了」）</p></li><li><p>10-14 23:25 后台访问数统计（「我先给后台搞个访问数统计」）</p></li><li><p>10-16 22:47 / 10-17 13:40 后台验证码登录（「管理员后台目前新增验证码登录，这是为了防止密码被逆向出来」）</p></li><li><p>10-17 13:41 后台登录记录（「还可以查看后台登录记录」）</p></li><li><p>10-17 23:30 / 10-18 02:06 手机端/电脑端设备选择与适配（「网站增加选择设备功能可以适配手机端和电脑端的大小」）</p></li><li><p>10-18 12:32 后台入口改为 /admin（「网站移除了主界面进后台的通道」「需要进后台在网址后面加上/admin」）</p></li><li><p>10-18 15:46 邀请码注册（「我搞了个邀请码」）</p></li><li><p>10-18 15:44-15:49 邮箱拉黑表（「检测到拉黑邮件直接不发验证码」「拉黑的进不去网站」）</p></li><li><p>10-18 16:36 管理员审核（「管理员可以审核了」）</p></li><li><p>10-19 20:29 客服（「用户可直接在后台咨询问题。由人工回答（类似于QQ）」）</p></li><li><p>10-20 00:54 客服可发图片（「客服聊天可以发图片了」）</p></li><li><p>10-20 01:27 客服可结束会话（「客服也可以结束会话了」）</p></li><li><p>10-20 19:28 管理员拉黑 IP（「管理员可手动拉黑IP地址」「以后这个IP就登不了网站了」）</p></li><li><p>10-21 21:04 「关于我们」页</p></li></ul></li></ol><p><span id="source-block-qxS5fuC0Z1AeOnDzQy5t8X"></span></p><h2 id="-8" tabindex="-1">================================================================ <a class="header-anchor" href="#-8" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【九】待做 / 待修的问题</p><ol><li><p>页面回不去（首页进子页后没有返回路径）<br> 谁提的：-（10-21 00:44），盒え猫 补充，K 给了修法<br> 结论：未修（已定位）<br> 原文：-「你页面逻辑之间没写好」「从首页跳转到其他任何页面，都回不去，只能重新进入站点」；<br> 盒え猫「工业看板和工业中心都能回去的吧」；<br> K「我看你给chat-nav-link的优先级是高一些的，那直接两个class一起用不就好了」</p></li><li><p>图片点开放大反而变小（没有滚轮缩放）<br> 谁提的：K（10-21 00:58-00:59）<br> 结论：未修<br> 原文：K「比如这个，好歹给点开后的加个滚轮放大缩小吧，这样的放大和没放大也没啥区别了（」<br> 「甚至还变小了一圈（」</p></li><li><p>换行解析不统一<br> 谁提的：K（10-21 00:50）<br> 结论：未修<br> 原文：「说起来什么时候加解析显示换行啊，我看技术文档那个页面的换行就是对的」</p></li><li><p>性能不够 / 加载慢<br> 谁提的：-（10-21 00:48-00:49）、味の薄いゆずゆず（10-20 19:02）、凯（10-15 22:48）<br> 结论：未解决（迁移服务器的主因之一）<br> 原文：-「肉眼看见性能不够用」→ JMY「那肯定」；-「那可能是他就这么设计的，加载的细节问题」；<br> 味の薄いゆずゆず「地图集标点开多了好卡好卡」「性能好像不太好」；凯「有点小卡」</p></li><li><p>移动端竖屏不兼容、要横屏才点得到<br> 谁提的：BEAR（10-17 23:11）<br> 结论：未修（之后做了设备选择，是否彻底解决未见确认）<br> 原文：BEAR「竖屏上分还有不兼容问题（」「得切横屏才能点得到」「拉不动」；<br> JMY「666我还得把手机端适配一下」；盒え猫「神秘的UI bug」</p></li><li><p>图片显示糊<br> 谁提的：断懒（10-22 03:27）<br> 结论：未定（原因未查明，疑为本地问题）<br> 原文：断懒「是我电脑的问题吗，感觉图好糊（」；言「这网站咋变成这样了」；鸟「这样是咋样，不是还挺好（」</p></li><li><p>搜索条/按钮的比例自适应 bug<br> 谁提的：盒え猫（10-21 00:34-00:36）<br> 结论：未修<br> 原文：盒え猫「以及有bug」「你这块为什么要加随着页面比例自适应（？」<br> 「给搜索条做一定程度的比例自适应」「然后留一个最小宽度」</p></li><li><p>蓝图投稿审核慢<br> 谁提的：Zirunwang（10-22 03:17）<br> 结论：未修<br> 原文：「现在你们蓝图分享的审核正常吗」「我这一个蓝图审核5分钟了」</p></li><li><p>投诉入口（待做）<br> 谁提的：JMY（10-22 19:39）<br> 结论：未做（已列入计划）<br> 原文：「下次我专门给网站搞个投诉入口吧」「别污染文档了」</p></li><li><p>客服体验：用户不应能自己结束对话<br> 谁提的：鸟（10-20 01:09），JMY 回应<br> 结论：未定（只回了「客服也可以结束会话了」）<br> 原文：鸟「能不能设置用户不能结束对话，只能由后台结束对话（」</p></li><li><p>登录/500 报错（已修）<br> 谁提的：JMY（10-20 00:33）<br> 结论：已修<br> 原文：「网页报500的bug修好了」「可以正常登录了」</p></li><li><p>内容更新效率低（自评）<br> 谁提的：JMY（10-20 00:48）<br> 结论：未解决（自述）<br> 原文：「窝网站更新的效率还是太低了」</p></li></ol><p><span id="source-block-fWBA2ubaLixjIN5tVquLNz"></span></p><h2 id="-9" tabindex="-1">================================================================ <a class="header-anchor" href="#-9" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【十】宣传与视觉</p><ol><li><p>宣传片：自己剪，走 B 站，参考苹果宣传片<br> 谁提的：JMY（10-18 11:34、10-19 19:37、10-20 00:13）<br> 结论：已定（在剪）<br> 原文：JMY「我自己剪一段视频介绍我自己的网站，你能不能下次发视频给视频末尾加上我剪的这个视频」→ 四卡一「可以的」；<br> JMY「体裁参考苹果宣传片」「宣传片准备参考Apple的宣传片」；<br> JMY「所以感觉我这个网站光在群里面说没啥大用所以要剪宣传片让sky周末发一下」</p></li><li><p>发不发：先小范围，别急着推<br> 谁提的：JMY（10-14 20:54）、-（10-14 21:27）<br> 结论：未定（被劝住）<br> 原文：JMY「感觉目前网站可以小范围推广了」；-「我建议不发，暂时还是半成品」；<br> 四卡一「我可以动态先推一波（」</p></li><li><p>联投与动态<br> 谁提的：盒え猫（10-19 19:19-19:20）、区（10-19 19:21）、四卡一（10-16 21:54）<br> 结论：未定（联投算不算激励有分歧）<br> 原文：盒え猫「记得联合投稿蹭流量（」「要么你网站直接用你自己的个人账号发（？」；<br> 鸟「联投算激励吗」→ 盒え猫「应该」→ 区「不算」；<br> 四卡一「完了，我网站的动态好像忘记发了」</p></li><li><p>UI 重设计：参考终末地官网<br> 谁提的：JMY（10-20 18:40、10-21 00:02）<br> 结论：进行中<br> 原文：「今天准备给网站的UI再重新设计一下」「参考终末地官网UI」「我再试试终末地官网同款配色」</p></li></ol><p><span id="source-block-KXSvPKmVLf3vJ1dVnMrUr0"></span></p><h2 id="-10" tabindex="-1">================================================================ <a class="header-anchor" href="#-10" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【十一】谁在做 / 分工</p><ol><li><p>网站开发：JMY 一个人<br> 谁提的：JMY 全程自述，多人可证<br> 结论：已定（事实上的一人开发）<br> 原文：JMY「写完作业继续弄网站」「今晚网站更新新功能」；<br> JMY（10-15 00:05）「从9号到15号我花了6天把这个网站搞的还能看」；<br> JMY（10-19 23:29）「满打满算从开始做网站到现在大概有两周多的时间」；<br> JMY（10-18 11:38）「网站尽量做到日更」</p></li><li><p>UI/概念设计：盒え猫（还没开始）<br> 谁提的：盒え猫（10-10 20:34、10-21 00:03）<br> 结论：未定（排队中）<br> 原文：盒え猫「所以后面需要设计界面的时候可以叫我（？」「和百亿」「但是我不太确定」「网页的前端要怎么设计」；<br> 盒え猫（10-21 00:03）「等我做完自动配平的视频我就来。。。」「做网页的概念设计」</p></li><li><p>文案/大纲：凯<br> 谁提的：凯（10-15 22:56、10-18 15:54）<br> 结论：已定（口头）<br> 原文：凯「@JMY 我决定上网站改文案」「避免腾讯文档移动端的恶心设计」「那我可能准备先写大纲了」</p></li><li><p>发动态/审核/宣传：四卡一<br> 谁提的：JMY（10-14 22:46、10-19 19:18）、四卡一（10-16 21:54）<br> 结论：已定（口头）<br> 原文：JMY「一会你有时间帮我发动态吗，咱一会再讨论一下网站的事」「这周天给你发我剪好的视频」；<br> 四卡一「我负责发激励收编」（语境是成果收编，非网站代码）</p></li><li><p>后台权限：言拿到管理员密码<br> 谁提的：JMY（10-15 20:40）<br> 结论：已定<br> 原文：「@言 网站后台密码已私发」</p></li><li><p>「要不要成立负责网站的部门」—— 提过，没落地<br> 谁提的：言（10-11 19:59）<br> 结论：未定<br> 原文：言「是不是能组出负责网站的部门」；沃沃奶糖「现在网站还在建设中没那么急」</p></li><li><p>技术栈/负责人/DDL 三问，没人回答<br> 谁提的：K（10-12 01:56）<br> 结论：未定<br> 原文：「所以专用网站什么时候初步上线，什么技术栈，搞云服务器还是自己搞服务器，具体网站谁来负责，要定个ddl吗」<br> （该条之后群聊转向别的，未见回答）</p></li></ol><p><span id="source-block-oV73EO2TNmn3WVCksKj5pz"></span></p><h2 id="-11" tabindex="-1">================================================================ <a class="header-anchor" href="#-11" aria-label="Permalink to &quot;================================================================&quot;">​</a></h2><p>【十二】存疑（拿不准，留待核对）</p><ol><li><p>「宏科院智网」到底算不算定了：JMY 只在 10-19 19:27 说「刚刚在直播间问老大了叫宏科院智网」，<br> 之后 10-20 22:55、10-22 18:44 又问「到底叫啥」，前后矛盾，无法判断是「老大定了」还是「提议」。</p></li><li><p>「skd」一词原文如此（10-21 00:51「方便调用skd数据」），推测指森空岛，但原文没写全称，未改。</p></li><li><p>10-21 00:50 的「70块钱一个月」与 10-13 23:59 的「一个月10刀」是否为同一档会员，原文未说明。</p></li><li><p>10-22 03:27「图好糊」与 10-21 00:59「放大反而变小」是否为同一图片组件问题，原文未确认。</p></li><li><p>10-17 23:30「网站增加选择设备功能」与 10-18 02:06「我把网站手机端的适配做了」是否同一改动，原文未说明。</p></li><li><p>「ENDFIELD 1.5 GUIDE」只出现在一段 HTML 的 title 里，是否是站点正式名，没人讨论过。</p></li><li><p>服务器价「一季度5000多」出现在 10-18 12:55，语境是本地跑大模型的机器，不是网站服务器，<br> 引用时需注意区分（原文紧接「不买了」「实在不行我自己先垫着买个服务器」）。</p></li></ol></div>',1)])])}const J=l(a,[["render",e]]);export{h as __pageData,J as default};
